        m.insert("bidVolume".to_string(), self.safe_string2(&message, Value::Str("B".into()), Value::Str("bidQty".into()), &[]));
        m.insert("ask".to_string(), self.safe_string2(&message, Value::Str("a".into()), Value::Str("askPrice".into()), &[]));
