    pub fn parse_ws_position(&self, position: impl Into<crate::Value>, market: Option<&crate::types::Market>) -> crate::value::Dict {
        let position: Value = position.into();
        //
        //     {
        //         "s": "BTCUSDT", // Symbol
        //         "pa": "0", // Position Amount
        //         "ep": "0.00000", // Entry Price
        //         "cr": "200", // (Pre-fee) Accumulated Realized
        //         "up": "0", // Unrealized PnL
        //         "mt": "isolated", // Margin Type
        //         "iw": "0.00000000", // Isolated Wallet (if isolated position)
        //         "ps": "BOTH" // Position Side
        //     }
        //
        let marketId: Option<String> = self.safe_string_k_opt(&position, "s", &[]);
        let contracts: Option<String> = self.safe_string_k_opt(&position, "pa", &[]);
        let contractsAbs: Option<String> = crate::precise::Precise::stringAbs(&self.safe_string_k(&position, "pa", &[])).as_str().map(str::to_owned);
        let mut positionSide: Option<String> = self.safe_string_lower_k_opt(&position, "ps", &[]);
        let mut hedged: bool = true;
        if (positionSide.as_deref() == Some("both")) {
            hedged = false;
            if !(crate::precise::Precise::stringEq(&contracts, &Value::Str("0".into())).as_bool() == Some(true)) {
                if crate::precise::Precise::stringLt(&contracts, &Value::Str("0".into())).as_bool() == Some(true) {
                    positionSide = Some("short".to_string());
                }  else {
                    positionSide = Some("long".to_string());
                }
            }
        }
        return self.safe_position(std::sync::Arc::new({
    let mut m = indexmap::IndexMap::new();
        m.insert("info".to_string(), position.clone());
        m.insert("id".to_string(), Value::Null);
        m.insert("symbol".to_string(), self.safe_symbol(marketId.as_deref(), None, &[Value::Null, Value::Str("swap".into())]));
        m.insert("notional".to_string(), Value::Null);
        m.insert("marginMode".to_string(), self.safe_string_k(&position, "mt", &[]));
        m.insert("liquidationPrice".to_string(), Value::Null);
        m.insert("entryPrice".to_string(), self.safe_number_k(&position, "ep", &[]));
        m.insert("unrealizedPnl".to_string(), self.safe_number_k(position, "up", &[]));
        m.insert("percentage".to_string(), Value::Null);
        m.insert("contracts".to_string(), self.parse_number(contractsAbs.map(Value::from).unwrap_or(Value::Null), &[]));
        m.insert("contractSize".to_string(), Value::Null);
        m.insert("markPrice".to_string(), Value::Null);
        m.insert("side".to_string(), positionSide.map(Value::from).unwrap_or(Value::Null));
        m.insert("hedged".to_string(), Value::Bool(hedged));
        m.insert("timestamp".to_string(), Value::Null);
        m.insert("datetime".to_string(), Value::Null);
        m.insert("maintenanceMargin".to_string(), Value::Null);
        m.insert("maintenanceMarginPercentage".to_string(), Value::Null);
        m.insert("collateral".to_string(), Value::Null);
        m.insert("initialMargin".to_string(), Value::Null);
        m.insert("initialMarginPercentage".to_string(), Value::Null);
        m.insert("leverage".to_string(), Value::Null);
        m.insert("marginRatio".to_string(), Value::Null);
    m
}));

    Default::default()
}

    pub fn parse_ws_options_position(&self, position: impl Into<crate::Value>, market: Option<&crate::types::Market>) -> crate::value::Dict {
        let position: Value = position.into();
        //
        //  from BALANCE_POSITION_UPDATE event P[] array:
        //  {
        //      "s": "BTC-251123-126000-C",  // option symbol
        //      "c": "-0.1000",              // position quantity (negative = short)
        //      "p": "-120.00000000",        // position value (USDT)
        //      "a": "1200.00000000"         // average entry price
        //  }
        //
        let marketId: Option<String> = self.safe_string_k_opt(&position, "s", &[]);
        let contracts: Option<String> = self.safe_string_k_opt(&position, "c", &[]);
        let contractsAbs: Option<String> = crate::precise::Precise::stringAbs(&contracts).as_str().map(str::to_owned);
        let mut side: Option<String> = None;
        if (contracts.is_some()) {
            if crate::precise::Precise::stringLt(&contracts, &Value::Str("0".into())).as_bool() == Some(true) {
                side = Some("short".to_string());
            }  else if crate::precise::Precise::stringGt(&contracts, &Value::Str("0".into())).as_bool() == Some(true) {
                side = Some("long".to_string());
            }
        }
        return self.safe_position(std::sync::Arc::new({
    let mut m = indexmap::IndexMap::new();
        m.insert("info".to_string(), position.clone());
        m.insert("id".to_string(), Value::Null);
        m.insert("symbol".to_string(), self.safe_symbol(marketId.as_deref(), market, &[Value::Null, Value::Str("option".into())]));
        m.insert("notional".to_string(), self.safe_string_k(&position, "p", &[]));
        m.insert("marginMode".to_string(), Value::Null);
        m.insert("liquidationPrice".to_string(), Value::Null);
        m.insert("entryPrice".to_string(), self.safe_number_k(position, "a", &[]));
        m.insert("unrealizedPnl".to_string(), Value::Null);
        m.insert("percentage".to_string(), Value::Null);
        m.insert("contracts".to_string(), self.parse_number(contractsAbs.map(Value::from).unwrap_or(Value::Null), &[]));
        m.insert("contractSize".to_string(), Value::Null);
        m.insert("markPrice".to_string(), Value::Null);
        m.insert("side".to_string(), side.map(Value::from).unwrap_or(Value::Null));
        m.insert("hedged".to_string(), Value::Bool(false));
        m.insert("timestamp".to_string(), Value::Null);
        m.insert("datetime".to_string(), Value::Null);
        m.insert("maintenanceMargin".to_string(), Value::Null);
        m.insert("maintenanceMarginPercentage".to_string(), Value::Null);
        m.insert("collateral".to_string(), Value::Null);
        m.insert("initialMargin".to_string(), Value::Null);
        m.insert("initialMarginPercentage".to_string(), Value::Null);
        m.insert("leverage".to_string(), Value::Null);
        m.insert("marginRatio".to_string(), Value::Null);
    m
}));

    Default::default()
}

